    // — 기타
    point: "0",
    descKr: `자유행성동맹 소속의 군인. 양 웬리의 부하이자 친구, 그리고 사관학교 후배. 재치와 과단성을 자랑하는 명장으로 빠른 기동력을 앞세운 허를 찌르는 날카로운 공격이 주특기. 사회에 대한 불평불만이 많고 독설가이며 전쟁을 싫어하지만 뛰어난 재능을 가지고 있다.`,
