    descKr: `라인하르트 폰 뮤젤 제독단의 균형형 제독. 테라 공략 중 테러리스트에게 독침을 맞아 왼팔을 잃고 의수를 달았다. 충직하고 안정적인 지휘로 제국군 내에서 신뢰받는 중견 제독이다.`,
