    // — 기본
    code: "CH_000514",
    nameKr: "프리드리히 폰 골덴바움 4세",
    nameEn: "Friedrich von Goldenbaum IV",
    nameJp: "フリードリヒ・フォン・ゴールデンバウム4世",
    nickKr: "프리드리히 4세",
    nickEn: "Friedrich IV",
    nickJp: "フリードリヒ4世",
